message.content:
{
  "description": "The creature is shown in right-facing side profile against a plain off-white background, standing low to the ground in a walking pose. It has a stout, elongated body with a pale pink, wrinkled, fleshy underside, throat, limbs and tail underside, and a broad, rounded head with a blunt snout. The entire dorsal surface from the back of the head to the tip of the long tapering tail is covered in large, overlapping, brown to gray-brown keratinous scales with darker edges and paler centers arranged in diagonal rows. Behind the head on both sides are prominent pink external gills with feathery red filaments. It stands on four thick, fleshy legs with clawed feet, and has small dark eyes and a closed mouth giving a slight smile.",
  "parts": [
    {
      "part": "head",
      "looks_like": "large, rounded and blunt-snouted, pale pink with soft wrinkled skin, small round nostril on the snout, large dark eye with a pale bluish iris and black pupil on the side, and a straight closed mouth line",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "eyes",
      "looks_like": "small, round, glossy, dark with a light blue-gray iris ring and black pupil, with a slight shine",
      "where": "on the side of the head, just behind and above the snout; the right eye is clearly visible, the left eye is just visible on the far side of the snout"
    },
    {
      "part": "gills",
      "looks_like": "six pink fleshy stalks with dense, feathery, reddish-pink filaments along their length, three on the near side curving outward behind the jaw/neck and three on the far side protruding above the head/neck",
      "where": "clustered immediately behind the head on both left and right sides of the neck"
    },
    {
      "part": "scales / plates",
      "looks_like": "large, overlapping, rounded keratinous scales, dark brown-gray at the edges fading to lighter tan-brown in the center with fine concentric ridges, arranged in overlapping diagonal rows like armor",
      "where": "covering the entire dorsal surface from the base of the gills along the back and sides down to the upper sides of the tail"
    },
    {
      "part": "skin / underbelly",
      "looks_like": "pale pink, soft, wrinkled and fleshy with transverse folds and creases, unscaled",
      "where": "on the ventral side of the body, throat, underside of the tail, and covering the limbs"
    },
    {
      "part": "markings",
      "looks_like": "small scattered dark gray-brown speckles and mottling",
      "where": "on the top and sides of the head, around the eyes and on the cheeks"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, columnar, pale pink wrinkled limbs with folded skin at the joints, muscular and bent in a walking stance",
      "where": "two forelegs under the chest/shoulder area and two hindlegs under the mid-body, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad, flat, five-toed with short blunt dark claws on each toe, pale pink with wrinkled skin on top",
      "where": "at the distal end of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick at the base and tapering to a point, dorsally covered in the same overlapping brown scales and ventrally pale pink wrinkled skin, with the very tip extending out of frame to the left",
      "where": "extending rearward from the back of the body to the left"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 6
}
